      SdkOptional<String> companyId = const SdkOmitted(),
      SdkOptional<bool> open = const SdkOmitted(),
      SdkOptional<bool> isShared = const SdkOmitted(),
      SdkOptional<int> snoozedUntil = const SdkOmitted(),
      SdkOptional<int> adminId = const SdkOmitted(),
      SdkOptional<String> assigneeId = const SdkOmitted(),
      SdkOptional<bool> skipNotifications = const SdkOmitted(),
